class BlockIdPromptModal extends Modal {
  constructor(app, plugin, source) {
    super(app);
    this.plugin = plugin;
    this.source = source;
    this.completed = false;
    this.submitting = false;
    this.input = null;
    this.previewEl = null;
    this.saveButton = null;
    this.awaitingSuggestion = false;
    this.suggestionResolved = false;
    this.userEdited = false;
    this.userMovedFocus = false;
    this.closed = false;
  }

  onOpen() {
    this.closed = false;
    this.contentEl.empty();
    this.contentEl.createEl("h2", { text: "Block ID" });
    this.createPreviewEl();
    this.loadPreview();

    const isExplicit =
      Boolean(this.source.prefillId) && Boolean(this.source.oldId);

    new Setting(this.contentEl).setName("ID").addText((text) => {
      this.input = text;
      text.setPlaceholder(isExplicit ? "my-id" : "Loading suggestion…");
      if (isExplicit) {
        text.setValue(this.source.oldId);
        this.suggestionResolved = true;
      }
      text.inputEl.addEventListener("input", () => {
        this.userEdited = true;
      });
      text.inputEl.addEventListener("blur", () => {
        this.userMovedFocus = true;
      });
      text.inputEl.addEventListener("keydown", (event) => {
        if (event.key !== "Enter") {
          return;
        }

        event.preventDefault();
        this.submit();
      });
    });

    new Setting(this.contentEl)
      .addButton((button) =>
        button
          .setButtonText("Cancel")
          .onClick(() => this.close()),
      )
      .addButton((button) => {
        this.saveButton = button;
        button
          .setButtonText("Save")
          .setCta()
          .onClick(() => this.submit());
        if (!isExplicit) {
          this.setSaveDisabled(true);
        }
      });

    if (isExplicit) {
      window.setTimeout(() => {
        if (this.closed || !this.input || !this.input.inputEl) {
          return;
        }
        if (!this.input.inputEl.isConnected) {
          return;
        }
        this.input.inputEl.focus();
        if (this.input.getValue()) {
          this.input.inputEl.select();
        }
      }, 0);
      return;
    }

    this.awaitingSuggestion = true;
    void this.resolveSuggestion();
  }

  setSaveDisabled(disabled) {
    const button = this.saveButton;
    if (!button) {
      return;
    }
    try {
      if (typeof button.setDisabled === "function") {
        button.setDisabled(Boolean(disabled));
        return;
      }
    } catch (error) {
      // Fall through to the DOM toggle below.
    }
    try {
      if (button.buttonEl) {
        button.buttonEl.disabled = Boolean(disabled);
      } else if (button.el) {
        button.el.disabled = Boolean(disabled);
      }
    } catch (error) {
      // Disabling Save is best effort; submit() still guards.
    }
  }

  async resolveSuggestion() {
    let result = null;
    try {
      result = await resolvePromptBlockIdSuggestion(this.plugin, this.source);
    } catch (error) {
      result = null;
    }

    if (this.closed) {
      return;
    }
    const input = this.input;
    if (!input || !input.inputEl || !input.inputEl.isConnected) {
      this.awaitingSuggestion = false;
      return;
    }

    this.awaitingSuggestion = false;
    this.suggestionResolved = true;
    this.setSaveDisabled(false);
    try {
      input.setPlaceholder("my-id");
    } catch (error) {
      // Placeholder is cosmetic; a missing setter never blocks seeding.
    }

    if (!result || result.explicit) {
      window.setTimeout(() => {
        if (this.closed || !this.input || !this.input.inputEl) {
          return;
        }
        if (!this.input.inputEl.isConnected) {
          return;
        }
        if (!this.userEdited && !this.userMovedFocus) {
          this.input.inputEl.focus();
        }
      }, 0);
      return;
    }

    if (result.notice) {
      try {
        new Notice(result.notice);
      } catch (error) {
        // Notices are best effort in headless test harnesses.
      }
    }

    const suggestion =
      typeof result.suggestion === "string" && result.suggestion
        ? result.suggestion
        : null;
    if (!suggestion) {
      window.setTimeout(() => {
        if (this.closed || !this.input || !this.input.inputEl) {
          return;
        }
        if (!this.input.inputEl.isConnected) {
          return;
        }
        if (!this.userEdited && !this.userMovedFocus) {
          this.input.inputEl.focus();
        }
      }, 0);
      return;
    }

    // A late result never overwrites typing (including clearing the field).
    if (this.userEdited) {
      return;
    }

    try {
      input.setValue(suggestion);
    } catch (error) {
      return;
    }

    // Select the untouched generated value once; never steal focus back
    // after the user has moved it elsewhere.
    if (this.userMovedFocus) {
      return;
    }
    const inputEl = input.inputEl;
    window.setTimeout(() => {
      if (this.closed || !this.input || this.input.inputEl !== inputEl) {
        return;
      }
      if (!inputEl.isConnected) {
        return;
      }
      if (this.userEdited || this.userMovedFocus) {
        return;
      }
      try {
        inputEl.focus();
        inputEl.select();
      } catch (error) {
        // Focus is best effort; the seeded value already stands.
      }
    }, 0);
  }

  createPreviewEl() {
    this.previewEl = this.contentEl.createEl("div", {
      text: "Loading block contents...",
    });
    this.previewEl.setAttribute("aria-label", "Current block contents");
    this.previewEl.setAttribute("role", "note");
    Object.assign(this.previewEl.style, {
      backgroundColor: "var(--background-secondary)",
      border: "1px solid var(--background-modifier-border)",
      borderRadius: "4px",
      color: "var(--text-muted)",
      lineHeight: "var(--line-height-normal)",
      margin: "0 0 12px 0",
      maxHeight: "12rem",
      overflowWrap: "anywhere",
      overflowY: "auto",
      padding: "10px 12px",
      userSelect: "text",
      whiteSpace: "pre-wrap",
    });
  }

  setPreviewText(text, muted) {
    if (!this.previewEl) {
      return;
    }

    this.previewEl.textContent = text;
    this.previewEl.style.color = muted
      ? "var(--text-muted)"
      : "var(--text-normal)";
  }

  async loadPreview() {
    const previewEl = this.previewEl;
    const previewText = await this.plugin.readBlockPreviewText(this.source);

    if (!previewEl || previewEl !== this.previewEl || !previewEl.isConnected) {
      return;
    }

    if (previewText) {
      this.setPreviewText(previewText, false);
    } else {
      this.setPreviewText("Block contents unavailable", true);
    }
  }

  async submit() {
    if (this.submitting) {
      return;
    }

    if (this.awaitingSuggestion) {
      return;
    }

    const id = this.input ? this.input.getValue().trim() : "";
    if (!id) {
      new Notice("Block ID cannot be blank");
      return;
    }

    if (!BLOCK_ID_RE.test(id)) {
      new Notice("Block ID can only contain letters, numbers, and hyphens");
      return;
    }

    this.submitting = true;
    try {
      const accepted = await this.plugin.submitBlockId(this.source, id);
      if (accepted) {
        this.completed = true;
        this.close();
      }
    } finally {
      this.submitting = false;
    }
  }

  onClose() {
    this.closed = true;
    this.awaitingSuggestion = false;
    this.contentEl.empty();

    if (!this.completed && !this.submitting) {
      this.plugin.cancelBlockIdPrompt(this.source);
    }

    this.plugin.lastPromptKey = null;
    this.plugin.promptOpen = false;
  }
}

class WorkSummaryPromptModal extends Modal {
  constructor(app, plugin, source) {
    super(app);
    this.plugin = plugin;
    this.source = source;
    this.workLogDate = localTodayParts(plugin.now());
    this.completed = false;
    this.submitting = false;
    this.inputEl = null;
    this.previewEl = null;
    this.warningEl = null;
    this.primaryButton = null;
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    this.modalEl.addClass("bid-wlp-modal");
    contentEl.addClass("bid-wlp");

    const header = contentEl.createDiv({ cls: "bid-wlp-header" });
    const headerIcon = header.createDiv({ cls: "bid-wlp-header-icon" });
    applyIcon(headerIcon, "pause-circle");
    const headerText = header.createDiv({ cls: "bid-wlp-header-text" });
    headerText.createDiv({ cls: "bid-wlp-title", text: "Unlink task" });
    headerText.createDiv({
      cls: "bid-wlp-subtitle",
      text: "Optional: why is this pending? Saved to the Work Log.",
    });

    const contextEl = contentEl.createDiv({
      cls: "bid-wlp-context",
      attr: { role: "note", "aria-label": "Selected task" },
    });
    contextEl.createDiv({
      cls: "bid-wlp-context-task",
      text: this.source.task && this.source.task.displayText
        ? this.source.task.displayText
        : "(untitled task)",
    });
    contextEl.createDiv({
      cls: "bid-wlp-context-source",
      text: this.source.contextPath || this.source.sourcePath || "Current note",
    });

    const fieldEl = contentEl.createDiv({ cls: "bid-wlp-field" });
    fieldEl.createEl("label", {
      cls: "bid-wlp-label",
      attr: { for: "bid-wlp-summary" },
      text: "Work summary (optional)",
    });
    this.inputEl = fieldEl.createEl("input", {
      cls: "bid-wlp-input",
      attr: {
        id: "bid-wlp-summary",
        "aria-describedby": "bid-wlp-preview bid-wlp-warning",
        placeholder: "What did you get done?",
        type: "text",
      },
    });
    this.inputEl.addEventListener("input", () => this.updatePreview());
    this.inputEl.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      this.submit();
    });

    this.previewEl = contentEl.createDiv({
      cls: "bid-wlp-preview",
      attr: { id: "bid-wlp-preview", role: "note", "aria-live": "polite" },
    });
    this.warningEl = contentEl.createDiv({
      cls: "bid-wlp-warning",
      attr: { id: "bid-wlp-warning", role: "status" },
      text: "Contains ::, which Dataview may read as an inline field.",
    });

    new Setting(contentEl)
      .addButton((button) =>
        button
          .setButtonText("Cancel")
          .onClick(() => this.close()),
      )
      .addButton((button) => {
        this.primaryButton = button;
        button
          .setButtonText("Unlink")
          .setCta()
          .onClick(() => this.submit());
      });

    this.updatePreview();
    window.setTimeout(() => {
      if (this.inputEl) {
        this.inputEl.focus();
      }
    }, 0);
  }

  updatePreview() {
    if (!this.previewEl) {
      return;
    }

    const state = workSummaryPromptState(this.inputEl ? this.inputEl.value : "", {
      date: this.workLogDate,
    });
    if (this.primaryButton && typeof this.primaryButton.setButtonText === "function") {
      this.primaryButton.setButtonText(state.primaryButtonText);
    }

    this.previewEl.empty();
    if (state.isBlank) {
      this.previewEl.setAttribute("aria-label", "No work-log entry will be added.");
      this.previewEl.createDiv({
        cls: "bid-wlp-preview-muted",
        text: "No work-log entry will be added.",
      });
    } else {
      this.previewEl.setAttribute("aria-label", state.formattedEntry);
      this.previewEl.createDiv({
        cls: "bid-wlp-preview-marker",
        text: `${WORK_LOG_EMOJI} **${WORK_LOG_LABEL}**`,
      });
      const entryEl = this.previewEl.createDiv({
        cls: "bid-wlp-preview-entry",
      });
      entryEl.createEl("em", {
        cls: "bid-wlp-preview-date",
        text: formatCalendarDate(state.date),
      });
      entryEl.createSpan({
        cls: "bid-wlp-preview-separator",
        text: WORK_LOG_ENTRY_SEPARATOR,
      });
      entryEl.createSpan({
        cls: "bid-wlp-preview-summary",
        text: state.summary,
      });
    }

    if (this.warningEl) {
      this.warningEl.toggleClass("is-hidden", !state.hasDataviewWarning);
    }
  }

  async submit() {
    if (this.submitting) {
      return;
    }

    this.submitting = true;
    try {
      const accepted = await this.plugin.submitPomodoroWorkSummary(
        this.source,
        this.inputEl ? this.inputEl.value : "",
        { workLogDate: this.workLogDate },
      );
      if (accepted) {
        this.completed = true;
        this.close();
      }
    } finally {
      this.submitting = false;
    }
  }

  onClose() {
    this.modalEl.removeClass("bid-wlp-modal");
    this.contentEl.empty();

    if (!this.completed && !this.submitting) {
      this.plugin.cancelWorkSummaryPrompt(this.source);
    }

    this.plugin.lastPromptKey = null;
    this.plugin.promptOpen = false;
  }
}

// ---- src/095-prompt-suggestion-resolver.js ----
// Source-to-suggestion resolver for prompt block IDs
// (plan 202610/task_block_id_prefill.md). All entry points converge on
// `openBlockIdPrompt`; the modal calls `resolvePromptBlockIdSuggestion`
// so gestures share one naming path. Pure naming lives in
// 015-prompt-block-id-naming.js; this fragment only resolves *which* task
// text and *which* note content seed it, preferring live editor buffers.

function findOpenPromptTargetEditors(plugin, targetPath) {
  const editors = [];
  try {
    const workspace = plugin && plugin.app && plugin.app.workspace;
    if (!workspace || typeof workspace.getLeavesOfType !== "function") {
      return editors;
    }
    const leaves = workspace.getLeavesOfType("markdown") || [];
    for (const leaf of leaves) {
      const view = leaf && leaf.view;
      if (
        !view ||
        !view.file ||
        view.file.path !== targetPath ||
        !view.editor ||
        typeof view.editor.getValue !== "function"
      ) {
        continue;
      }
      try {
        editors.push({
          editor: view.editor,
          content: String(view.editor.getValue() || ""),
        });
      } catch (error) {
        continue;
      }
    }
  } catch (error) {
    return editors;
  }
  return editors;
}

// Authoritative target snapshot: same-note reads use the source editor;
// cross-note reads prefer an open target editor (unsaved wins over disk),
// otherwise the vault. Multiple disagreeing live buffers refuse instead of
// guessing. Returns `{ content, editor }` or `{ content: null, ambiguous }`.
async function readAuthoritativePromptTargetContent(plugin, source, targetFile) {
  if (
    targetFile &&
    targetFile.path === source.sourcePath &&
    source.editor &&
    typeof source.editor.getValue === "function"
  ) {
    try {
      return { content: String(source.editor.getValue() || ""), editor: source.editor };
    } catch (error) {
      return { content: null, editor: null, error: true };
    }
  }

  if (!targetFile) {
    return { content: null, editor: null, error: true };
  }

  const openEditors = findOpenPromptTargetEditors(plugin, targetFile.path);
  if (openEditors.length === 1) {
    return { content: openEditors[0].content, editor: openEditors[0].editor };
  }
  if (openEditors.length > 1) {
    const first = openEditors[0].content;
    const agrees = openEditors.every((entry) => entry.content === first);
    if (!agrees) {
      return { content: null, editor: null, ambiguous: true };
    }
    return { content: first, editor: openEditors[0].editor };
  }

  try {
    const content = await plugin.app.vault.read(targetFile);
    if (typeof content !== "string") {
      return { content: null, editor: null, error: true };
    }
    return { content, editor: null };
  } catch (error) {
    return { content: null, editor: null, error: true };
  }
}

function getDirectAddPromptRootLine(source) {
  try {
    if (!source || !source.editor || typeof source.editor.getValue !== "function") {
      return null;
    }
    const lines = String(source.editor.getValue() || "").split("\n");
    const start = source.rangeStartLine;
    const end = source.rangeEndLine;
    if (
      !Number.isInteger(start) ||
      !Number.isInteger(end) ||
      start < 0 ||
      end >= lines.length ||
      start > end
    ) {
      return null;
    }
    if (typeof source.expectedBlockText === "string") {
      const current = lineRangeText(lines, start, end);
      if (current !== source.expectedBlockText) {
        return null;
      }
    }
    const rootLine = lines[start];
    if (promptBlockIdExtractTaskBody(rootLine) === null) {
      return null;
    }
    return rootLine;
  } catch (error) {
    return null;
  }
}

// Resolve which suggestion (if any) seeds the modal. Returns
// `{ suggestion, notice }`; `suggestion` is null for blank (non-task,
// explicit rename handled by the caller, or unresolvable). `notice` uses the
// existing submit-path wording so failures look identical before/after Save.
async function resolvePromptBlockIdSuggestion(plugin, source) {
  try {
    if (!source) {
      return { suggestion: null, notice: null };
    }

    // Explicit renames win unchanged; the modal prefills oldId synchronously.
    if (source.prefillId && source.oldId) {
      return { suggestion: null, notice: null, explicit: true };
    }

    if (source.kind === "direct-add") {
      const rootLine = getDirectAddPromptRootLine(source);
      if (rootLine === null) {
        return { suggestion: null, notice: null };
      }
      let content = "";
      try {
        content = String(source.editor.getValue() || "");
      } catch (error) {
        return { suggestion: null, notice: "Block ID add blocked: active note could not be read" };
      }
      return {
        suggestion: suggestPromptBlockId(rootLine, content, { reservedIds: new Set() }),
        notice: null,
      };
    }

    if (source.kind === "link-task-complete") {
      const task = source.task;
      if (!task || typeof task.rawLine !== "string") {
        return { suggestion: null, notice: null };
      }
      const targetFile = plugin.resolveDestinationFile
        ? plugin.resolveDestinationFile(source)
        : null;
      if (!targetFile) {
        return {
          suggestion: null,
          notice: "Task link blocked: target note could not be resolved",
        };
      }
      const snapshot = await readAuthoritativePromptTargetContent(plugin, source, targetFile);
      if (snapshot.content === null) {
        if (snapshot.ambiguous) {
          return {
            suggestion: null,
            notice: `Task link blocked: ${targetFile.path} changed before update`,
          };
        }
        return {
          suggestion: null,
          notice: "Task link blocked: target note could not be resolved",
        };
      }
      const currentLine = contentLineAt(snapshot.content, task.line);
      if (currentLine === null || currentLine !== task.rawLine) {
        return {
          suggestion: null,
          notice: `Task link blocked: selected task changed in ${targetFile.path}`,
        };
      }
      return {
        suggestion: suggestPromptBlockId(task.rawLine, snapshot.content, {
          reservedIds: new Set(),
        }),
        notice: null,
      };
    }

    if (source.kind === "link-task-pomodoro") {
      const task = source.task;
      if (!task || typeof task.rawLine !== "string") {
        return { suggestion: null, notice: null };
      }
      if (!source.editor || typeof source.editor.getValue !== "function") {
        return { suggestion: null, notice: "Task link blocked: active note could not be read" };
      }
      const currentLine = source.editor.getLine(source.line);
      if (currentLine !== task.rawLine) {
        return {
          suggestion: null,
          notice: `Task link blocked: selected task changed in ${source.sourcePath}`,
        };
      }
      let content = "";
      try {
        content = String(source.editor.getValue() || "");
      } catch (error) {
        return { suggestion: null, notice: "Task link blocked: active note could not be read" };
      }
      return {
        suggestion: suggestPromptBlockId(task.rawLine, content, { reservedIds: new Set() }),
        notice: null,
      };
    }

    // Marker-triggered rename: oldId present without an explicit prefill flag.
    // Suggest only for uniquely resolved task blocks; never hide ambiguity by
    // globally removing duplicates (exclude exactly one occurrence).
    if (source.oldId && !source.prefillId) {
      const targetFile = plugin.resolveDestinationFile
        ? plugin.resolveDestinationFile(source)
        : null;
      if (!targetFile) {
        return {
          suggestion: null,
          notice: "Block ID rename blocked: target note could not be resolved",
        };
      }
      const snapshot = await readAuthoritativePromptTargetContent(plugin, source, targetFile);
      if (snapshot.content === null) {
        if (snapshot.ambiguous) {
          return {
            suggestion: null,
            notice: `Block ID rename blocked: ${targetFile.path} changed before rename`,
          };
        }
        return {
          suggestion: null,
          notice: "Block ID rename blocked: target note could not be resolved",
        };
      }
      const occurrences = promptBlockIdCountOccurrences(snapshot.content, source.oldId);
      if (occurrences !== 1) {
        return {
          suggestion: null,
          notice: `Block ID rename blocked: old ID was not found exactly once in ${targetFile.path}`,
        };
      }
      const lines = snapshot.content.split("\n");
      let targetLine = null;
      for (const line of lines) {
        if (promptBlockIdCountOccurrences(line, source.oldId) === 1) {
          // The line holds the unique token; confirm it is the token form
          // (not a coincidental substring) via the shared token matcher.
          if (blockTokenMatches(line, source.oldId).length === 1) {
            targetLine = line;
            break;
          }
        }
      }
      if (targetLine === null) {
        return {
          suggestion: null,
          notice: `Block ID rename blocked: old ID was not found exactly once in ${targetFile.path}`,
        };
      }
      if (promptBlockIdExtractTaskBody(targetLine) === null) {
        return { suggestion: null, notice: null };
      }
      return {
        suggestion: suggestPromptBlockId(targetLine, snapshot.content, {
          reservedIds: new Set(),
          excludeId: source.oldId,
        }),
        notice: null,
      };
    }

    return { suggestion: null, notice: null };
  } catch (error) {
    return { suggestion: null, notice: null };
  }
}
// ---- src/100-plugin-lifecycle.js ----
class BlockIdPromptPlugin extends Plugin {
  onload() {
    this.promptOpen = false;
    this.activePomodoroLinkPicker = null;
    this.scanTimer = null;
    this.scanView = null;
    this.suppressUntil = 0;
    this.lastPromptKey = null;
    // Versioned Pomodoro link picker api (docs/task-dependencies.md
    // §12.13): nav feature-detects `api?.pomodoroLinkPicker?.version >= 1`.
    this.api = Object.freeze({
      pomodoroLinkPicker: createPomodoroLinkPickerApi(this),
    });

    this.addCommand({
      id: "rename-selected-block-id",
      name: "Rename selected block ID",
      hotkeys: [{ modifiers: ["Ctrl"], key: "6" }],
      editorCallback: (editor, view) =>
        this.openSelectedBlockIdPrompt(editor, view),
    });

    this.addCommand({
      id: "link-task-to-pomodoro",
      name: "Toggle task Pomodoro link",
      hotkeys: [{ modifiers: ["Ctrl", "Shift"], key: "Enter" }],
      editorCallback: (editor, view) =>
        this.openPomodoroTaskLink(editor, view),
    });

    this.registerEditorExtension(
      EditorView.updateListener.of((update) => this.scheduleScan(update)),
    );

    this.register(() => {
      if (this.scanTimer !== null) {
        window.clearTimeout(this.scanTimer);
      }
    });
  }

  scheduleScan(update) {
    if (!update.docChanged) {
      return;
    }

    if (this.promptOpen) {
      return;
    }

    this.scanView = update.view;
    if (this.scanTimer !== null) {
      window.clearTimeout(this.scanTimer);
    }

    this.scanTimer = window.setTimeout(() => {
      this.scanTimer = null;
      this.inspectActiveEditor(this.scanView);
      this.scanView = null;
    }, SCAN_DEBOUNCE_MS);
  }

  inspectActiveEditor(cmView) {
    if (this.promptOpen) {
      return;
    }

    const scansSuppressed = Date.now() < this.suppressUntil;
    const view = this.app.workspace.getActiveViewOfType(MarkdownView);
    if (!(view instanceof MarkdownView) || !view.editor) {
      return;
    }

    if (view.editor.cm && cmView && view.editor.cm !== cmView) {
      return;
    }

    if (!this.hasSingleCursor(view.editor)) {
      return;
    }

    const file = view.file || this.app.workspace.getActiveFile();
    if (!(file instanceof TFile) || file.extension !== "md") {
      return;
    }

    const cursor = view.editor.getCursor();
    if (!cursor || !Number.isInteger(cursor.line)) {
      return;
    }

    const lineText = view.editor.getLine(cursor.line) || "";
    const taskMarker = findTaskPickerMarkerNearCursor(lineText, cursor.ch || 0);
    if (taskMarker) {
      if (lineIsInsideCodeFence(view.editor, cursor.line)) {
        return;
      }

      void this.openTaskLinkPicker({
        ...taskMarker,
        editor: view.editor,
        sourcePath: file.path,
        line: cursor.line,
      });
      return;
    }

    if (scansSuppressed) {
      return;
    }

    const marker = findMarkerLinkNearCursor(lineText, cursor.ch || 0);
    if (!marker) {
      this.lastPromptKey = null;
      return;
    }

    if (lineIsInsideCodeFence(view.editor, cursor.line)) {
      return;
    }

    if (marker.kind === "file-link-jump") {
      this.applyFileLinkJumpMarker(marker, view.editor, cursor.line);
      return;
    }

    const source = {
      ...marker,
      editor: view.editor,
      sourcePath: file.path,
      line: cursor.line,
    };
    this.openBlockIdPrompt(source);
  }

  openSelectedBlockIdPrompt(editor, view) {
    if (this.promptOpen) {
      return;
    }

    const markdownView =
      view instanceof MarkdownView
        ? view
        : this.app.workspace.getActiveViewOfType(MarkdownView);
    if (!(markdownView instanceof MarkdownView) || !editor) {
      new Notice("No active Markdown block selected");
      return;
    }

    const file = markdownView.file || this.app.workspace.getActiveFile();
    if (!(file instanceof TFile) || file.extension !== "md") {
      new Notice("No active Markdown block selected");
      return;
    }

    if (!this.hasSingleCursor(editor)) {
      new Notice("No active Markdown block selected");
      return;
    }

    const selection = getSingleEditorSelection(editor);
    const cursor = selection && selection.head;
    if (!isEditorPosition(cursor)) {
      new Notice("No active Markdown block selected");
      return;
    }

    if (lineIsInsideCodeFence(editor, cursor.line)) {
      return;
    }

    const lineText = editor.getLine(cursor.line) || "";
    const blockReference = findBlockReferenceOnLine(
      lineText,
      cursor.ch || 0,
    );
    if (blockReference) {
      this.openBlockIdPrompt({
        ...blockReference,
        editor,
        sourcePath: file.path,
        line: cursor.line,
      });
      return;
    }

    const result = discoverSelectedBlockIdSource(editor, file);
    if (!result || !result.source) {
      new Notice(
        (result && result.notice) || "No active Markdown block selected",
      );
      return;
    }

    this.openBlockIdPrompt(result.source);
  }

  openBlockIdPrompt(source) {
    if (this.promptOpen) {
      return;
    }

    const key = sourceKey(source);
    if (key === this.lastPromptKey) {
      return;
    }

    this.lastPromptKey = key;
    this.promptOpen = true;
    new BlockIdPromptModal(this.app, this, source).open();
  }

  async openTaskLinkPicker(source) {
    if (this.promptOpen) {
      return;
    }

    const key = sourceKey(source);
    if (key === this.lastPromptKey) {
      return;
    }

    this.lastPromptKey = key;
    this.promptOpen = true;

    try {
      const destination = await this.readDestinationForValidation(source);
      if (!destination) {
        new Notice("Task link blocked: target note could not be resolved");
        this.lastPromptKey = null;
        this.promptOpen = false;
        return;
      }

      if (destination.content === null) {
        new Notice(`Task link blocked: ${destination.file.path} could not be read`);
        this.lastPromptKey = null;
        this.promptOpen = false;
        return;
      }

      if (!this.sourceMarkerStillPresent(source, { quiet: true })) {
        this.lastPromptKey = null;
        this.promptOpen = false;
        return;
      }

      const tasks = collectTaskPickerItems(destination.content);
      new TaskLinkPickerModal(
        this.app,
        this,
        {
          ...source,
          destinationPath: destination.file.path,
        },
        tasks,
        destination.file,
      ).open();
    } catch (error) {
      console.error("Block ID Prompt failed to open task link picker", error);
      new Notice("Task link blocked: target note could not be read");
      this.lastPromptKey = null;
      this.promptOpen = false;
    }
  }

  cancelTaskLinkPicker(source) {
    this.revertTaskPickerMarker(source, { quiet: true });
  }

  async selectTaskLinkTask(source, task) {
    if (task.existingId) {
      return this.completeTaskLinkWithExistingId(source, task);
    }

    if (!this.sourceMarkerStillPresent(source)) {
      return null;
    }

    return {
      promptSource: {
        ...source,
        kind: "link-task-complete",
        task: { ...task },
        previewText: task.displayText,
        prefillId: false,
      },
    };
  }

  async completeTaskLinkWithExistingId(source, task) {
    if (!this.sourceMarkerStillPresent(source)) {
      return null;
    }

    const destination = await this.readDestinationForValidation(source);
    if (!destination || destination.content === null) {
      new Notice("Task link blocked: target note could not be resolved");
      return null;
    }

    if (!this.taskLineStillPresent(destination.content, task, destination.file.path)) {
      return null;
    }

    const currentId = getTrailingBlockId(task.rawLine);
    if (currentId !== task.existingId) {
      new Notice("Task link blocked: selected task block ID changed");
      return null;
    }

    const activationEligible = sourceQualifiesForPomodoroActivation(source);
    const plan = planTargetTaskUpdate(destination.content, task.line, {
      activationEligible,
      now: this.now(),
      stampLine: this.getFreshnessStampLine(),
      freshDateText: this.getFreshnessDateText(),
    });
    if (!plan) {
      new Notice(`Task link stopped: selected task changed in ${destination.file.path}`);
      return null;
    }

    if (plan.hasChanges) {
      if (
        !(await this.applyTargetTaskPlan(destination.file, source, plan, destination.content))
      ) {
        return null;
      }
    }

    const completionSource = this.adjustSourceForPlan(source, destination.file.path, plan);
    const completion = this.completeTaskSourceLink(
      completionSource,
      task.existingId,
      destination.file.path,
    );
    if (!completion) {
      if (plan.hasChanges) {
        const parts = activationPartialFailureParts(plan);
        new Notice(
          `Task ${parts.length ? parts.join(", ") : "linked"}, but the source link changed before completion`,
        );
      }
      return null;
    }

    new Notice(
      `Linked task block${activationSuccessSuffix(plan)}${this.futureLinkCleanupNoticeSuffix(completion.removedCount)}`,
    );
    return { completed: true };
  }

  hasSingleCursor(editor) {
    if (
      !editor ||
      typeof editor.getCursor !== "function" ||
      typeof editor.getLine !== "function" ||
      typeof editor.replaceRange !== "function"
    ) {
      return false;
    }

    if (typeof editor.listSelections !== "function") {
      return true;
    }

    const selections = editor.listSelections();
    return Array.isArray(selections) && selections.length === 1;
  }

  cancelBlockIdPrompt(source) {
    if (source.kind === "link-task-complete") {
      this.revertTaskPickerMarker(source, { quiet: true });
      return;
    }

    if (source.kind === "link-task-pomodoro") {
      // A cancelled block-ID prompt stays: settle without advancing.
      this.settleLinkReviewOrigin(source, null);
      return;
    }

    if (
      source.kind === "direct-add" ||
      source.kind === "direct-rename" ||
      source.kind === "link-block"
    ) {
      return;
    }

    this.replaceSourceLink(source, source.oldId, { quiet: true });
  }

  applyFileLinkJumpMarker(marker, editor, line) {
    if (!editor || typeof editor.getLine !== "function") {
      return false;
    }

    const lineText = editor.getLine(line) || "";
    if (lineText.slice(marker.startCh, marker.endCh) !== marker.raw) {
      return false;
    }

    this.suppressEditorScans();
    if (!dispatchFileLinkBlockCompletion(editor, line, marker)) {
      applyFileLinkBlockCompletionWithEditorApi(editor, line, marker);
    }
    this.lastPromptKey = null;
    return true;
  }

  onunload() {
    try {
      this.closePomodoroLinkPickerForUnload();
    } catch (_error) {
      this.activePomodoroLinkPicker = null;
    }
    // Drop the picker capability first so nav retargeting degrades to no
    // hint the moment this plugin unloads (mixed-version sessions never
    // call into a torn-down picker).
    try {
      this.api = Object.freeze({
        pomodoroLinkPicker: createPomodoroLinkPickerApi(null),
      });
    } catch (_error) {
      // Best effort: Obsidian is tearing down.
    }
  }
}
// ---- src/110-plugin-block-id-submit.js ----
class BlockIdPromptBlockIdSubmitMixin {
  async submitBlockId(source, newId) {
    if (source.kind === "direct-add") {
      return this.submitDirectBlockAdd(source, newId);
    }

    if (source.kind === "direct-rename") {
      return this.submitDirectBlockRename(source, newId);
    }

    if (source.kind === "link-task-complete") {
      return this.submitLinkTaskBlockId(source, newId);
    }

    if (source.kind === "link-task-pomodoro") {
      return this.submitPomodoroTaskLinkBlockId(source, newId);
    }

    return this.submitLinkedBlockId(source, newId);
  }

  async submitLinkedBlockId(source, newId) {
    if (!this.sourceMarkerStillPresent(source)) {
      return false;
    }

    const destination = await this.readDestinationForValidation(source);
    if (!destination || destination.content === null) {
      new Notice("Block ID rename blocked: target note could not be resolved");
      return false;
    }

    if (newId !== source.oldId) {
      const duplicateMatches = blockTokenMatches(destination.content, newId);
      if (duplicateMatches.length > 0) {
        new Notice(`Block ID '${newId}' already exists in ${destination.file.path}`);
        return false;
      }
    }

    const oldMatches = blockTokenMatches(destination.content, source.oldId);
    if (oldMatches.length !== 1) {
      new Notice(
        `Block ID rename blocked: old ID was not found exactly once in ${destination.file.path}`,
      );
      return false;
    }

    const plan = await this.buildReferenceRewritePlan(source, destination, newId);
    if (!plan) {
      return false;
    }

    if (plan.unsupportedCount > 0) {
      new Notice(
        `Block ID rename blocked: ${plan.unsupportedCount} old ${pluralize(
          plan.unsupportedCount,
          "link",
          "links",
        )} could not be rewritten safely`,
      );
      return false;
    }

    if (!(await this.applyReferenceRewritePlan(plan, source))) {
      return true;
    }

    if (
      !(await this.renameDestinationBlock(
        destination.file,
        source,
        source.oldId,
        newId,
        plan.destinationContentAfterReferences,
      ))
    ) {
      return true;
    }

    if (newId === source.oldId) {
      new Notice(
        `Updated ${plan.editCount} ${pluralize(plan.editCount, "link", "links")}`,
      );
    } else {
      new Notice(
        `Renamed block ID and updated ${plan.editCount} ${pluralize(
          plan.editCount,
          "link",
          "links",
        )}`,
      );
    }

    return true;
  }

  async submitDirectBlockRename(source, newId) {
    if (!this.directRenameSourceStillPresent(source)) {
      return false;
    }

    const destination = await this.readDestinationForValidation(source);
    if (!destination || destination.content === null) {
      new Notice("Block ID rename blocked: target note could not be resolved");
      return false;
    }

    if (newId !== source.oldId) {
      const duplicateMatches = blockTokenMatches(destination.content, newId);
      if (duplicateMatches.length > 0) {
        new Notice(`Block ID '${newId}' already exists in ${destination.file.path}`);
        return false;
      }
    }

    const oldMatches = blockTokenMatches(destination.content, source.oldId);
    if (oldMatches.length !== 1) {
      new Notice(
        `Block ID rename blocked: old ID was not found exactly once in ${destination.file.path}`,
      );
      return false;
    }

    const plan = await this.buildReferenceRewritePlan(
      source,
      destination,
      newId,
      { requireSourceMarker: false },
    );
    if (!plan) {
      return false;
    }

    if (plan.unsupportedCount > 0) {
      new Notice(
        `Block ID rename blocked: ${plan.unsupportedCount} old ${pluralize(
          plan.unsupportedCount,
          "link",
          "links",
        )} could not be rewritten safely`,
      );
      return false;
    }

    if (!(await this.applyReferenceRewritePlan(plan, source))) {
      return true;
    }

    if (
      !(await this.renameDestinationBlock(
        destination.file,
        source,
        source.oldId,
        newId,
        plan.destinationContentAfterReferences,
      ))
    ) {
      return true;
    }

    if (newId === source.oldId) {
      new Notice(
        `Updated ${plan.editCount} ${pluralize(plan.editCount, "link", "links")}`,
      );
    } else {
      new Notice(
        `Renamed block ID and updated ${plan.editCount} ${pluralize(
          plan.editCount,
          "link",
          "links",
        )}`,
      );
    }

    return true;
  }

  submitDirectBlockAdd(source, newId) {
    if (!this.directAddSourceStillPresent(source)) {
      return false;
    }

    const content = source.editor.getValue();
    const duplicateMatches = blockTokenMatches(content, newId);
    if (duplicateMatches.length > 0) {
      new Notice(`Block ID '${newId}' already exists in ${source.sourcePath}`);
      return false;
    }

    this.suppressEditorScans();
    if (source.addMode === "append") {
      source.editor.replaceRange(
        ` ^${newId}`,
        { line: source.line, ch: source.startCh },
        { line: source.line, ch: source.endCh },
      );
    } else {
      source.editor.replaceRange(
        `\n^${newId}`,
        { line: source.line, ch: source.startCh },
        { line: source.line, ch: source.endCh },
      );
    }

    new Notice("Added block ID");
    return true;
  }

  async submitLinkTaskBlockId(source, newId) {
    if (!this.sourceMarkerStillPresent(source)) {
      return false;
    }

    const destination = await this.readDestinationForValidation(source);
    if (!destination || destination.content === null) {
      new Notice("Task link blocked: target note could not be resolved");
      return false;
    }

    const duplicateMatches = blockTokenMatches(destination.content, newId);
    if (duplicateMatches.length > 0) {
      new Notice(`Block ID '${newId}' already exists in ${destination.file.path}`);
      return false;
    }

    if (!this.taskLineStillPresent(destination.content, source.task, destination.file.path)) {
      return false;
    }

    const activationEligible = sourceQualifiesForPomodoroActivation(source);
    const plan = planTargetTaskUpdate(destination.content, source.task.line, {
      newBlockId: newId,
      activationEligible,
      now: this.now(),
      stampLine: this.getFreshnessStampLine(),
      freshDateText: this.getFreshnessDateText(),
    });
    if (!plan) {
      new Notice(`Task link stopped: selected task changed in ${destination.file.path}`);
      return false;
    }

    if (
      !(await this.applyTargetTaskPlan(destination.file, source, plan, destination.content))
    ) {
      return false;
    }

    const completionSource = this.adjustSourceForPlan(source, destination.file.path, plan);
    const completion = this.completeTaskSourceLink(
      completionSource,
      newId,
      destination.file.path,
    );
    if (!completion) {
      const parts = activationPartialFailureParts(plan);
      new Notice(
        `Task block ID added${parts.length ? ` and ${parts.join(", ")}` : ""}, but the source link changed before completion`,
      );
      return true;
    }

    new Notice(
      `Added block ID and linked task${activationSuccessSuffix(plan)}${this.futureLinkCleanupNoticeSuffix(completion.removedCount)}`,
    );
    return true;
  }

}
